import json, pathlib, statistics, html
root=pathlib.Path(__file__).resolve().parents[2]
summary=json.loads((root/'local-results/development-summary.json').read_text())
lines=['# First labeled development comparison','','This is a development result, not a held-out acceptance test. All personal post text, source URLs, labels, and full results remain in ignored local-results/. The counts below are aggregate findings.','','## Sample','','Rory labeled 20 real For You previews: 16 keep, 2 hide, and 2 insufficient-evidence cases. Both hide examples use the tech-only rule; there are no labeled hide examples for dating, withheld-point, or combined rules yet. With 16 wanted cases, the 95% retention target requires keeping all 16. With only two unwanted cases, these percentages are highly unstable.','','## Comparison','','Thresholds below are chosen on these development cases to preserve all 16 wanted posts. They must not be represented as frozen product thresholds or validated probabilities.','','| Candidate | Template | Wanted kept | Unwanted hidden | Median actual-rule call |','|---|---|---:|---:|---:|']
for r in summary:
 lines.append(f"| {r['candidate']} {r['dtype']} | {r['template']} | {r['kept_at_threshold']}/16 | {r['hidden_at_threshold']}/2 | {r['median_actual_call_ms']:.1f} ms |")
lines+=['','`choice` uses explicit keep/hide options with the original instruction. `state` puts the user instruction in the state JSON; `question` puts it in a fixed question wrapper. `direct` is a hand-written yes/no question for each known rule type, with polarity explicitly mapped to keep probability. Direct questions are a diagnostic of task formulation, not a demonstrated general plain-language-rule solution.','','The six `minimal-` formats keep every user instruction verbatim. Prefix and suffix put a fixed question after or before it. State uses `{filter, post}` with a fixed question. Choice supplies named keep/hide options. AB and BA use neutral option keys with reversed keep/hide meanings. Every minimal format also runs empty-instruction and explicit keep-all controls.','','## Interpretation','','A monotonic threshold cannot repair incorrectly ordered wanted/unwanted scores. Calibration and the ability to separate classes must be assessed separately. The controls with an empty rule and an explicit keep-all rule record actual model behavior; their scores must not be treated as the intended production behavior before a user supplies preferences.','','Held-back post/instruction cases have not been inferred or used to change these templates. The final 40-case balanced test still requires enough human labels. No model is selected from this pass.','','## Runtime scope','','Apple M4 / 16 GB, Chromium 155, WebGPU, standalone browser page. Models loaded one at a time. First-call and warm-call measurements remain distinct. Full process/GPU peak memory, sustained scrolling and packaged-extension measurements remain outstanding.']
(root/'measurements/development-report.md').write_text('\n'.join(lines)+'\n')
# No personal text, individual labels, or example URLs are included in this aggregate.
aggregate=[{k:v for k,v in r.items() if k!='uncertain_p_keep'} for r in summary]
(root/'measurements/development-aggregate.json').write_text(json.dumps(aggregate,indent=2))

configs=[('opendecider','q8f16'),('opendecider','fp16'),('laya','fp32-fp16-embeddings')]
lookup={(r['candidate'],r['dtype'],r['template']):r for r in summary}
parts=['<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Development evaluation results</title><style>body{font:15px/1.5 system-ui;background:#f5f5f2;color:#233129;max-width:1000px;margin:30px auto;padding:0 24px}h1{font-size:28px}.panel{background:white;border:1px solid #d4dfd1;border-radius:12px;padding:20px;margin:18px 0}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:8px;border-bottom:1px solid #e0e5dc;font-size:14px}.muted{color:#63705d}.verdict{font-size:20px;font-weight:600}strong{color:#294f35}</style>', '<h1>Verbatim-instruction comparison</h1><p class="muted">20 labeled For You previews · 16 keep / 2 hide / 2 uncertain · Apple M4, WebGPU</p>', '<div class="panel"><p class="verdict">Development evidence only; no model selected.</p><p>Each cell counts unwanted posts hidden at a threshold preserving all 16 wanted posts. The target requires hiding both unwanted posts. Both are tech-relevance cases; broader rule coverage and held-out testing remain outstanding.</p><p>All six new formats preserve the user instruction verbatim. Empty-instruction and keep-all baselines run separately.</p></div>']
for title,modes in [('New minimal wrappers',['minimal-prefix','minimal-suffix','minimal-state','minimal-choice','minimal-ab','minimal-ba']),('Earlier diagnostic comparison',['state','question','choice','direct'])]:
 parts.append(f'<div class="panel"><h2>{title}</h2><table><tr><th>Format</th><th>OpenDecider q8f16</th><th>OpenDecider fp16</th><th>Laya multilingual</th></tr>')
 for mode in modes:
  parts.append('<tr><td>'+html.escape(mode)+'</td>')
  for candidate,dtype in configs:
   r=lookup.get((candidate,dtype,mode))
   parts.append('<td>'+ (f"{r['hidden_at_threshold']}/2 hidden · {r['median_actual_call_ms']:.0f} ms" if r else 'Pending')+'</td>')
  parts.append('</tr>')
 parts.append('</table><p class="muted">Median single-post actual-instruction call shown. Each row uses its own development-selected threshold; these are not production thresholds.</p></div>')
parts.append('<div class="panel"><h2>How to read this</h2><p>Prefix/suffix move the fixed question around the unchanged instruction. State uses filter and post fields. Choice names the keep/hide answers. AB and BA reverse the meanings attached to neutral answer keys.</p><p>Direct questions rewrite each known rule into a hand-written diagnostic question; they are not a general solution for arbitrary user instructions.</p><p>Strictness only changes the threshold. Softmax normalization is not evidence of calibration, and temperature scaling cannot fix an incorrect ranking.</p><p class="muted">Private text and labels remain local. Held-out cases have not been scored. Standalone-page timing excludes extension integration, sustained scrolling, and peak memory.</p></div>')
(root/'prototypes/model-evaluation/report.html').write_text('\n'.join(parts)+'\n')
